import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { RequiredFuelComponent } from './required-fuel.component';

const routes: Routes = [{ path: '', component: RequiredFuelComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class RequiredFuelRoutingModule { }
