import { Component, OnInit, ViewChild } from '@angular/core';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { GResponse } from '../../../../core/common/GResponse';
import { Urls } from '../../../../core/common/Urls';
import { G } from '../../../../core/common/G';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { IonContent, AlertController, LoadingController, ToastController } from '@ionic/angular';
import { GAccount } from '../../../../core/common/GAccount';
import { CourseService } from '../../../../data/service/course/course.service';
import { SliderService } from '../../../../data/service/site/Slider.service';

@Component({
  selector: 'app-required-fuel',
  templateUrl: './required-fuel.component.html',
  styleUrls: ['./required-fuel.component.scss']
})
export class RequiredFuelComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  isShow = false;
  isCheck = true;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  tunerPlusVideo: string | SafeUrl = '5NU8e';

  numsquirts = '1';
  injectorstaging = '1';
  afr = '14.7';

  form: FormGroup;
  reqfuel = 11.2;
  dreqfuel = 11.2;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private siteService: SliderService,
    private courseService: CourseService
  ) {
    this.isShow = false;
    if (!GAccount.IsLoggedIn()) {
      this.router.navigateByUrl('/Account');
    }
    this.check();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(17).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.tunerPlusVideo = G.TunerPlusReqFuelVideo;

    this.form = this.fb.group({
      enginedisplacement: [2000, [Validators.required, Validators.min(1), Validators.max(16000)]],
      numcylinders: [4, [Validators.required, Validators.min(1), Validators.max(16)]],
      numinjectors: [4, [Validators.required, Validators.min(1), Validators.max(16)]],
      injectorflow: [300, [Validators.required, Validators.min(1), Validators.max(30000)]],
      // numsquirts: [1, [Validators.required, Validators.min(1), Validators.max(8)]],
      // injectorstaging: [1, [Validators.required, Validators.min(0), Validators.max(3)]],
      // afr: [14.7, [Validators.required, Validators.min(1), Validators.max(40)]]
    });
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onCalc() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          const yourreqfuel =
            this.Reqfuel(
              ((this.form.value.enginedisplacement / 1000) * 61),
              this.form.value.numcylinders,
              this.form.value.numinjectors,
              this.form.value.injectorflow / 10.5,
              +this.numsquirts,
              +this.injectorstaging,
              +this.afr
            );

          this.reqfuel = Math.round(yourreqfuel) / 10;

          const yourdreqfuel = this.Dreqfuel(
            ((this.form.value.enginedisplacement / 1000) * 61),
            this.form.value.numcylinders,
            this.form.value.numinjectors,
            this.form.value.injectorflow / 10.5,
            +this.numsquirts,
            +this.injectorstaging,
            +this.afr
          );

          this.dreqfuel = Math.round(yourdreqfuel) / 10;

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  Reqfuel(enginedisplacement2, numcylinders2, numinjectors2, injectorflow2, numsquirts2, injectorstaging2, afr2) {
    const reqfuelndx = (1543 * enginedisplacement2) / (numcylinders2 * afr2 * injectorflow2);
    return reqfuelndx;
  }

  Dreqfuel(enginedisplacement1, numcylinders1, numinjectors1, injectorflow1, numsquirts1, injectorstaging1, afr1) {

    const dreqfuelndx = (1543 * enginedisplacement1) / (numcylinders1 * (numinjectors1 / numcylinders1) * afr1 * injectorflow1 * numsquirts1 * injectorstaging1);
    return dreqfuelndx;
  }

  onReset() {

    this.numsquirts = '1';
    this.injectorstaging = '1';
    this.afr = '14.7';
    this.reqfuel = 11.2;
    this.dreqfuel = 11.2;
    this.form.setValue({
      enginedisplacement: 2000,
      numcylinders: 4,
      numinjectors: 4,
      injectorflow: 300
    });
  }

  onInfo(type: string) {

    switch (type) {
      case 'enginedisplacement':
        this.presentActiveAlertConfirm('حجم موتور برحسب سی سی (cc)');
        break;
      case 'numcylinders':
        this.presentActiveAlertConfirm('تعداد سیلندر');
        break;
      case 'numinjectors':
        this.presentActiveAlertConfirm('تعداد انژکتور');
        break;
      case 'injectorflow':
        this.presentActiveAlertConfirm('حجم انژکتور برحسب سی سی بر دقیقه (cc/min)');
        break;
      case 'numsquirts':
        this.presentActiveAlertConfirm('تعداد سیکل پاشش');
        break;
      case 'injectorstaging':
        this.presentActiveAlertConfirm('استیج پاشش');
        break;
      case 'afr':
        this.presentActiveAlertConfirm('نوع سوخت');
        break;

      default:
        break;
    }
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.tunerPlusVideo +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.tunerPlusVideo;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }
}
